//! Output directory management: write-if-changed, generation manifest and
//! stale-file cleanup.

use std::collections::BTreeSet;
use std::path::{Component, Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::error::{Error, IoContext, Result};

/// Name of the manifest file written into the output directory.
pub const MANIFEST_FILE: &str = ".blogen-manifest.json";

/// Manifest recording the files generated by the previous build.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct Manifest {
    version: u32,
    files: Vec<String>,
}

/// Statistics of one build's output phase.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct OutputSummary {
    /// Files written (new or changed).
    pub written: usize,
    /// Files whose content was already up to date.
    pub unchanged: usize,
    /// Stale files removed from the previous build.
    pub removed: usize,
}

/// Writer for the generated site directory.
///
/// All paths handled by this type are relative to the output root and are
/// validated against traversal. Writes are skipped when the content is
/// unchanged, keeping mtimes stable for incremental deployments.
#[derive(Debug)]
pub struct Output {
    root: PathBuf,
    clean: bool,
    previous: BTreeSet<String>,
    generated: BTreeSet<String>,
    summary: OutputSummary,
}

impl Output {
    /// Open (and create if needed) the output directory.
    pub fn new(root: impl Into<PathBuf>, clean: bool) -> Result<Self> {
        let root = root.into();
        std::fs::create_dir_all(&root)
            .with_context(|| format!("creating output directory `{}`", root.display()))?;
        let previous = if clean {
            read_manifest(&root)?
        } else {
            BTreeSet::new()
        };
        Ok(Self {
            root,
            clean,
            previous,
            generated: BTreeSet::new(),
            summary: OutputSummary::default(),
        })
    }

    /// Output directory root.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Write a file at `relative_path` (always `/` separated) with the given
    /// bytes. Returns `true` when the file was actually written.
    pub fn write(&mut self, relative_path: &str, contents: &[u8]) -> Result<bool> {
        let relative_path = normalize_relative(relative_path)?;
        let target = self.root.join(&relative_path);
        self.generated.insert(relative_path.clone());

        if target.is_file() {
            let existing = std::fs::read(&target)
                .with_context(|| format!("reading existing output `{}`", target.display()))?;
            if existing == contents {
                self.summary.unchanged += 1;
                return Ok(false);
            }
        }
        if let Some(parent) = target.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("creating output directory `{}`", parent.display()))?;
        }
        std::fs::write(&target, contents)
            .with_context(|| format!("writing output file `{}`", target.display()))?;
        self.summary.written += 1;
        Ok(true)
    }

    /// Write a UTF-8 file.
    pub fn write_str(&mut self, relative_path: &str, contents: &str) -> Result<bool> {
        self.write(relative_path, contents.as_bytes())
    }

    /// Finish the build: write the manifest and remove stale files.
    pub fn finish(mut self) -> Result<OutputSummary> {
        let manifest = Manifest {
            version: 1,
            files: self.generated.iter().cloned().collect(),
        };
        let serialized = serde_json::to_vec_pretty(&manifest).map_err(|err| Error::Io {
            context: "serializing the generation manifest".to_string(),
            source: std::io::Error::other(err),
        })?;
        std::fs::write(self.root.join(MANIFEST_FILE), serialized).with_context(|| {
            format!(
                "writing generation manifest `{}`",
                self.root.join(MANIFEST_FILE).display()
            )
        })?;

        if self.clean {
            for stale in self.previous.difference(&self.generated) {
                let path = self.root.join(stale);
                if path.is_file() {
                    std::fs::remove_file(&path)
                        .with_context(|| format!("removing stale output `{}`", path.display()))?;
                    self.summary.removed += 1;
                    self.prune_empty_parents(&path);
                }
            }
        }
        Ok(self.summary)
    }

    fn prune_empty_parents(&self, file: &Path) {
        let mut current = file.parent();
        while let Some(dir) = current {
            if dir == self.root || !dir.starts_with(&self.root) {
                break;
            }
            match std::fs::read_dir(dir) {
                Ok(mut entries) => {
                    if entries.next().is_some() {
                        break;
                    }
                }
                Err(_) => break,
            }
            if std::fs::remove_dir(dir).is_err() {
                break;
            }
            current = dir.parent();
        }
    }
}

fn read_manifest(root: &Path) -> Result<BTreeSet<String>> {
    let path = root.join(MANIFEST_FILE);
    if !path.is_file() {
        return Ok(BTreeSet::new());
    }
    let source = std::fs::read(&path)
        .with_context(|| format!("reading generation manifest `{}`", path.display()))?;
    let manifest: Manifest = serde_json::from_slice(&source).map_err(|err| Error::Io {
        context: format!(
            "parsing generation manifest `{}` (delete it to rebuild from scratch)",
            path.display()
        ),
        source: std::io::Error::other(err),
    })?;
    Ok(manifest.files.into_iter().collect())
}

/// Remove all files recorded in the output directory's manifest.
///
/// Returns the number of removed files. When no manifest exists, nothing is
/// removed; pass `force = true` to delete the whole output directory instead.
pub fn clean_output(root: &Path, force: bool) -> Result<usize> {
    if !root.exists() {
        return Ok(0);
    }
    if force {
        std::fs::remove_dir_all(root)
            .with_context(|| format!("removing output directory `{}`", root.display()))?;
        return Ok(1);
    }
    let previous = read_manifest(root)?;
    let mut removed = 0;
    for relative in previous {
        let path = root.join(&relative);
        if path.is_file() {
            std::fs::remove_file(&path)
                .with_context(|| format!("removing output file `{}`", path.display()))?;
            removed += 1;
        }
    }
    let manifest = root.join(MANIFEST_FILE);
    if manifest.is_file() {
        std::fs::remove_file(&manifest)
            .with_context(|| format!("removing manifest `{}`", manifest.display()))?;
    }
    Ok(removed)
}

/// Write a file outside the output directory (for example the profile README),
/// skipping the write when the content is unchanged.
///
/// Returns `true` when the file was written.
pub fn write_file_if_changed(path: &Path, contents: &[u8]) -> Result<bool> {
    if path.is_file() {
        let existing = std::fs::read(path)
            .with_context(|| format!("reading existing file `{}`", path.display()))?;
        if existing == contents {
            return Ok(false);
        }
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating directory `{}`", parent.display()))?;
    }
    std::fs::write(path, contents).with_context(|| format!("writing file `{}`", path.display()))?;
    Ok(true)
}

/// Validate and normalize an output-relative path.
pub fn normalize_relative(relative_path: &str) -> Result<String> {
    if relative_path.is_empty() {
        return Err(Error::UnsafePath {
            path: PathBuf::from(relative_path),
            message: "path is empty".to_string(),
        });
    }
    let path = Path::new(relative_path);
    let mut parts = Vec::new();
    for component in path.components() {
        match component {
            Component::Normal(part) => parts.push(part.to_string_lossy().to_string()),
            Component::CurDir => {}
            Component::ParentDir => {
                return Err(Error::UnsafePath {
                    path: PathBuf::from(relative_path),
                    message: "`..` is not allowed".to_string(),
                })
            }
            Component::RootDir | Component::Prefix(_) => {
                return Err(Error::UnsafePath {
                    path: PathBuf::from(relative_path),
                    message: "absolute paths are not allowed".to_string(),
                })
            }
        }
    }
    if parts.is_empty() {
        return Err(Error::UnsafePath {
            path: PathBuf::from(relative_path),
            message: "path does not name a file".to_string(),
        });
    }
    Ok(parts.join("/"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_and_skips_unchanged_files() {
        let temp = tempfile::tempdir().unwrap();
        let mut output = Output::new(temp.path(), true).unwrap();
        assert!(output.write_str("a/b.txt", "hello").unwrap());
        assert!(!output.write_str("a/b.txt", "hello").unwrap());
        assert!(output.write_str("a/b.txt", "world").unwrap());
        let summary = output.finish().unwrap();
        assert_eq!(summary.written, 2);
        assert_eq!(summary.unchanged, 1);
        assert_eq!(
            std::fs::read_to_string(temp.path().join("a/b.txt")).unwrap(),
            "world"
        );
    }

    #[test]
    fn removes_stale_files_from_manifest() {
        let temp = tempfile::tempdir().unwrap();
        let mut output = Output::new(temp.path(), true).unwrap();
        output.write_str("old.html", "old").unwrap();
        output.finish().unwrap();
        assert!(temp.path().join("old.html").is_file());

        let mut output = Output::new(temp.path(), true).unwrap();
        output.write_str("new.html", "new").unwrap();
        let summary = output.finish().unwrap();
        assert_eq!(summary.removed, 1);
        assert!(!temp.path().join("old.html").exists());
        assert!(temp.path().join("new.html").is_file());
    }

    #[test]
    fn keeps_stale_files_when_clean_disabled() {
        let temp = tempfile::tempdir().unwrap();
        let mut output = Output::new(temp.path(), false).unwrap();
        output.write_str("old.html", "old").unwrap();
        output.finish().unwrap();

        let mut output = Output::new(temp.path(), false).unwrap();
        output.write_str("new.html", "new").unwrap();
        output.finish().unwrap();
        assert!(temp.path().join("old.html").is_file());
    }

    #[test]
    fn rejects_unsafe_paths() {
        assert!(normalize_relative("../x").is_err());
        assert!(normalize_relative("/etc/passwd").is_err());
        assert!(normalize_relative("").is_err());
        assert_eq!(normalize_relative("a/./b").unwrap(), "a/b");
    }

    #[test]
    fn prunes_empty_directories() {
        let temp = tempfile::tempdir().unwrap();
        let mut output = Output::new(temp.path(), true).unwrap();
        output.write_str("dir/sub/old.html", "old").unwrap();
        output.finish().unwrap();

        let mut output = Output::new(temp.path(), true).unwrap();
        output.write_str("new.html", "new").unwrap();
        output.finish().unwrap();
        assert!(!temp.path().join("dir").exists());
    }
}
